{-| @Backend.Runtime.Host.Foreign — the dynamic loader behind native foreign calls: a library opened with the interpreter's candidates in its order, a symbol found once, and E7015 in its words. -}
module Pudu.Backend.Runtime.Host.Foreign (hostForeignParts, foreignLoaderMarker) where

import Data.Text (Text)
import Pudu.Backend.Toolchain.HostSources (loaderSourceLines, sqliteSourceMarker)

{-| The line whose presence in a program's C says the program needs the dynamic loader. -}
foreignLoaderMarker :: Text
foreignLoaderMarker = "/* pudu host loader */"

{-| Each part: its name, the parts it needs, and its lines. -}
hostForeignParts :: [(Text, [Text], [Text])]
hostForeignParts =
  [ ("host_foreign_sqlite", [],
      [ sqliteSourceMarker
      , "/* The SQLite binding is built into the program, as it is into the"
      , "   interpreter, and answers its own symbols. */"
      , "#define PUDU_HOST_SQLITE 1"
      , "void *pudu_sqlite_symbol(const char *name);"
      , "static char pudu_foreign_sqlite_module;"
      ])
  , ("host_foreign", ["fail", "memory_failure", "host_math"],
      [foreignLoaderMarker] <> loaderSourceLines <>
      [ "#include <stdatomic.h>"
      , "#if !defined(_WIN32)"
      , "#include <pthread.h>"
      , "#endif"
      , "/* A reference the linker keeps, so the math library stays loaded where the"
      , "   platform links it only when used, and `c` sees the math functions as the"
      , "   interpreter's process does. */"
      , "double (*pudu_foreign_math)(double, double) = pow;"
      , "/* One declaration's resolved function, kept for the life of the program. */"
      , "typedef void (*pudu_foreign_proc)(void);"
      , "typedef struct { _Atomic(pudu_foreign_proc) function; } pudu_foreign_cache;"
      , "static pudu_foreign_proc pudu_foreign_cached(const pudu_foreign_cache *cache) {"
      , "  return atomic_load_explicit(&cache->function, memory_order_acquire);"
      , "}"
      , "#if defined(_WIN32)"
      , "static SRWLOCK pudu_foreign_lock = SRWLOCK_INIT;"
      , "static void pudu_foreign_enter(void) { AcquireSRWLockExclusive(&pudu_foreign_lock); }"
      , "static void pudu_foreign_leave(void) { ReleaseSRWLockExclusive(&pudu_foreign_lock); }"
      , "#else"
      , "static pthread_mutex_t pudu_foreign_lock = PTHREAD_MUTEX_INITIALIZER;"
      , "static void pudu_foreign_enter(void) { pthread_mutex_lock(&pudu_foreign_lock); }"
      , "static void pudu_foreign_leave(void) { pthread_mutex_unlock(&pudu_foreign_lock); }"
      , "#endif"
      , "/* Stops the program at the call with the interpreter's E7015 message. */"
      , "static void pudu_foreign_refuse(const pudu_site *site, const char *symbol, const char *library, const char *release, const char *problem) {"
      , "  char message[4096];"
      , "  int written = snprintf(message, sizeof message, \"cannot call %s in %s: %s%s%s%s\", symbol, library, release == NULL ? \"\" : \"release \", release == NULL ? \"\" : release, release == NULL ? \"\" : \": \", problem);"
      , "  size_t length = written < 0 ? 0 : (size_t)written >= sizeof message ? sizeof message - 1 : (size_t)written;"
      , "  pudu_foreign_leave();"
      , "  pudu_fail_message(site, message, length);"
      , "}"
      , "/* Appends one candidate file name; the written name comes first, then the"
      , "   versioned spellings, then the plain ones, as the interpreter tries them. */"
      , "static void pudu_foreign_candidate(char names[][512], int *count, const char *prefix, const char *name, const char *middle, const char *version, const char *suffix) {"
      , "  int written = snprintf(names[*count], 512, \"%s%s%s%s%s\", prefix, name, middle, version == NULL ? \"\" : version, suffix);"
      , "  if (written >= 0 && written < 512) *count += 1;"
      , "}"
      , "static void *pudu_foreign_open(const pudu_site *site, const char *library, const char *version, const char *symbol, const char *producer) {"
      , "  char names[13][512], tried[4096], error[1024] = {0};"
      , "  int count = 0;"
      , "  size_t used = 0;"
      , "  void *handle;"
      , "#ifdef PUDU_HOST_SQLITE"
      , "  if (strcmp(library, \"pudu_sqlite\") == 0) return &pudu_foreign_sqlite_module;"
      , "#endif"
      , "  if (strcmp(library, \"c\") == 0) {"
      , "    handle = pudu_loader_open(NULL, 0);"
      , "    if (handle == NULL) pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, \"the program cannot see its own symbols\");"
      , "    return handle;"
      , "  }"
      , "  handle = pudu_loader_open(library, 0);"
      , "  if (handle != NULL) return handle;"
      , "  pudu_loader_error(error, sizeof error);"
      , "  if (version != NULL) {"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \".so.\", version, \"\");"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \".\", version, \".dylib\");"
      , "    pudu_foreign_candidate(names, &count, \"lib\", library, \"-\", version, \".dll\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \".so.\", version, \"\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \".\", version, \".dylib\");"
      , "    pudu_foreign_candidate(names, &count, \"\", library, \"-\", version, \".dll\");"
      , "  }"
      , "  pudu_foreign_candidate(names, &count, \"lib\", library, \"\", NULL, \".dylib\");"
      , "  pudu_foreign_candidate(names, &count, \"lib\", library, \"\", NULL, \".so\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".dylib\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".so\");"
      , "  pudu_foreign_candidate(names, &count, \"\", library, \"\", NULL, \".dll\");"
      , "#if defined(_WIN32)"
      , "  pudu_foreign_candidate(names, &count, \"lib\", library, \"\", NULL, \".dll\");"
      , "#endif"
      , "  for (int i = 0; i < count; ++i) {"
      , "    handle = pudu_loader_open(names[i], 0);"
      , "    if (handle != NULL) return handle;"
      , "  }"
      , "  used = (size_t)snprintf(tried, sizeof tried, \"could not open the library; tried %s\", library);"
      , "  for (int i = 0; i < count && used < sizeof tried; ++i)"
      , "    used += (size_t)snprintf(tried + used, sizeof tried - used, \", %s\", names[i]);"
      , "  if (used < sizeof tried && error[0] != 0)"
      , "    (void)snprintf(tried + used, sizeof tried - used, \" (%s)\", error);"
      , "  pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, tried);"
      , "  return NULL;"
      , "}"
      , "typedef struct pudu_foreign_library {"
      , "  struct pudu_foreign_library *next;"
      , "  const char *name, *version;"
      , "  void *handle;"
      , "} pudu_foreign_library;"
      , "static pudu_foreign_library *pudu_foreign_libraries;"
      , "static int pudu_foreign_libraries_finish_registered;"
      , "static void pudu_foreign_libraries_finish(void) {"
      , "  while (pudu_foreign_libraries != NULL) {"
      , "    pudu_foreign_library *entry = pudu_foreign_libraries;"
      , "    pudu_foreign_libraries = entry->next;"
      , "    free(entry);"
      , "  }"
      , "}"
      , ""
      , "/* Called under the loader lock. Foreign declarations can retain"
      , "   symbols beyond a call, so these references last for the process. */"
      , "static void *pudu_foreign_module(const pudu_site *site, const char *name, const char *version, const char *symbol, const char *producer) {"
      , "  for (pudu_foreign_library *entry = pudu_foreign_libraries; entry != NULL; entry = entry->next)"
      , "    if (strcmp(name, entry->name) == 0 &&"
      , "        (version == entry->version || (version != NULL && entry->version != NULL && strcmp(version, entry->version) == 0)))"
      , "      return entry->handle;"
      , "  if (!pudu_foreign_libraries_finish_registered) {"
      , "    if (atexit(pudu_foreign_libraries_finish) != 0) pudu_memory_failure();"
      , "    pudu_foreign_libraries_finish_registered = 1;"
      , "  }"
      , "  void *handle = pudu_foreign_open(site, name, version, symbol, producer);"
      , "  pudu_foreign_library *entry = malloc(sizeof *entry);"
      , "  if (entry == NULL) pudu_memory_failure();"
      , "  *entry = (pudu_foreign_library){pudu_foreign_libraries, name, version, handle};"
      , "  pudu_foreign_libraries = entry;"
      , "  return handle;"
      , "}"
      , ""
      , "static pudu_foreign_proc pudu_foreign_function(const pudu_site *site, pudu_foreign_cache *cache, const char *library, const char *version, const char *symbol, const char *producer) {"
      , "  pudu_foreign_proc function = pudu_foreign_cached(cache);"
      , "  if (function != NULL) return function;"
      , "  pudu_foreign_enter();"
      , "  function = pudu_foreign_cached(cache);"
      , "  if (function == NULL) {"
      , "    void *handle = pudu_foreign_module(site, library, version, symbol, producer);"
      , "#ifdef PUDU_HOST_SQLITE"
      , "    void *address = handle == &pudu_foreign_sqlite_module ? pudu_sqlite_symbol(symbol) : pudu_loader_symbol(handle, symbol);"
      , "#else"
      , "    void *address = pudu_loader_symbol(handle, symbol);"
      , "#endif"
      , "    if (address == NULL) {"
      , "      char problem[600];"
      , "      snprintf(problem, sizeof problem, \"the library exports no %s\", symbol);"
      , "      pudu_foreign_refuse(site, producer == NULL ? symbol : producer, library, producer == NULL ? NULL : symbol, problem);"
      , "    }"
      , "    _Static_assert(sizeof(function) == sizeof(address), \"loader function pointer size\");"
      , "    memcpy(&function, &address, sizeof function);"
      , "    atomic_store_explicit(&cache->function, function, memory_order_release);"
      , "  }"
      , "  pudu_foreign_leave();"
      , "  return function;"
      , "}"
      ])
  , ("host_foreign_block", [],
      [ "#if !defined(__APPLE__)"
      , "#error \"an Objective-C block crossing needs an Apple target\""
      , "#endif"
      , "/* A stack block with no copy or dispose helpers, followed by the"
      , "   registration key. A callee that keeps it copies it with the key. */"
      , "typedef struct {"
      , "  unsigned long reserved, size;"
      , "} pudu_foreign_block_descriptor;"
      , "typedef struct {"
      , "  void *isa;"
      , "  int flags, reserved;"
      , "  void *invoke;"
      , "  const pudu_foreign_block_descriptor *descriptor;"
      , "  uintptr_t key;"
      , "} pudu_foreign_block;"
      , "extern void *_NSConcreteStackBlock[32];"
      , "static const pudu_foreign_block_descriptor pudu_foreign_block_shape = {0, sizeof(pudu_foreign_block)};"
      ])
  , ("host_objc_delegate", ["host_foreign", "host_foreign_store", "host_callback"],
      [ "#if !defined(__APPLE__)"
      , "#error \"an Objective-C delegate needs an Apple target\""
      , "#endif"
      , "/* The Objective-C runtime is resolved as any library is. A delegate"
      , "   object keeps its registration key in its extra bytes. */"
      , "static void *(*pudu_delegate_extra)(void *) = NULL;"
      , "static void *pudu_delegate_runtime(const pudu_site *site, pudu_foreign_cache *cache, const char *symbol) {"
      , "  return (void *)pudu_foreign_function(site, cache, \"/usr/lib/libobjc.A.dylib\", NULL, symbol, NULL);"
      , "}"
      , "static uintptr_t pudu_delegate_key(void *object) {"
      , "  uintptr_t key = 0;"
      , "  if (object != NULL && pudu_delegate_extra != NULL) memcpy(&key, pudu_delegate_extra(object), sizeof key);"
      , "  return key;"
      , "}"
      , "static void *pudu_delegate_class(const pudu_site *site, const char *name, size_t count,"
      , "    const char *const *selectors, void *const *methods, const char *const *encodings) {"
      , "  static pudu_foreign_cache lookup = {NULL}, allocate = {NULL}, add = {NULL}, publish = {NULL},"
      , "    discard = {NULL}, named = {NULL}, extra = {NULL};"
      , "  void *(*class_of)(const char *) = (void *(*)(const char *))pudu_delegate_runtime(site, &lookup, \"objc_getClass\");"
      , "  if (pudu_delegate_extra == NULL)"
      , "    pudu_delegate_extra = (void *(*)(void *))pudu_delegate_runtime(site, &extra, \"object_getIndexedIvars\");"
      , "  void *existing = class_of(name);"
      , "  if (existing != NULL) return existing;"
      , "  void *(*allocate_pair)(void *, const char *, size_t) ="
      , "    (void *(*)(void *, const char *, size_t))pudu_delegate_runtime(site, &allocate, \"objc_allocateClassPair\");"
      , "  signed char (*add_method)(void *, void *, void *, const char *) ="
      , "    (signed char (*)(void *, void *, void *, const char *))pudu_delegate_runtime(site, &add, \"class_addMethod\");"
      , "  void (*publish_pair)(void *) = (void (*)(void *))pudu_delegate_runtime(site, &publish, \"objc_registerClassPair\");"
      , "  void (*discard_pair)(void *) = (void (*)(void *))pudu_delegate_runtime(site, &discard, \"objc_disposeClassPair\");"
      , "  void *(*selector_of)(const char *) = (void *(*)(const char *))pudu_delegate_runtime(site, &named, \"sel_registerName\");"
      , "  void *base = class_of(\"NSObject\");"
      , "  void *created = base == NULL ? NULL : allocate_pair(base, name, 0);"
      , "  if (created == NULL) return NULL;"
      , "  for (size_t i = 0; i < count; ++i)"
      , "    if (!add_method(created, selector_of(selectors[i]), methods[i], encodings[i])) {"
      , "      discard_pair(created);"
      , "      return NULL;"
      , "    }"
      , "  publish_pair(created);"
      , "  return created;"
      , "}"
      , "static void *pudu_delegate_instance(const pudu_site *site, void *type, uintptr_t key) {"
      , "  static pudu_foreign_cache create = {NULL};"
      , "  void *(*instance_of)(void *, size_t) ="
      , "    (void *(*)(void *, size_t))pudu_delegate_runtime(site, &create, \"class_createInstance\");"
      , "  void *object = instance_of(type, sizeof(uintptr_t));"
      , "  if (object != NULL) memcpy(pudu_delegate_extra(object), &key, sizeof key);"
      , "  return object;"
      , "}"
      , "static void pudu_delegate_release(uint64_t address) {"
      , "  static const pudu_site site = {.file = \"<foreign delegate>\", .line = 1, .column = 1, .code = \"E7001\","
      , "    .message = \"the Objective-C runtime is unavailable\"};"
      , "  static pudu_foreign_cache send = {NULL}, named = {NULL};"
      , "  void (*release)(void *, void *) = (void (*)(void *, void *))pudu_delegate_runtime(&site, &send, \"objc_msgSend\");"
      , "  void *(*selector_of)(const char *) = (void *(*)(const char *))pudu_delegate_runtime(&site, &named, \"sel_registerName\");"
      , "  release((void *)(uintptr_t)address, selector_of(\"release\"));"
      , "}"
      ])
  , ("host_objc", ["host_foreign"],
      [ "typedef struct {"
      , "  pudu_foreign_cache dispatcher;"
      , "  _Atomic(void *) receiver, selector;"
      , "} pudu_objc_cache;"
      , ""
      , "static inline void *pudu_objc_selector(const pudu_objc_cache *cache) {"
      , "  return atomic_load_explicit(&cache->selector, memory_order_acquire);"
      , "}"
      , "static inline void *pudu_objc_receiver(const pudu_objc_cache *cache) {"
      , "  return atomic_load_explicit(&cache->receiver, memory_order_acquire);"
      , "}"
      , ""
      , "static pudu_foreign_proc pudu_objc_prepare(const pudu_site *site, pudu_objc_cache *cache,"
      , "                                          const char *library, const char *version,"
      , "                                          const char *selector, const char *class_name,"
      , "                                          size_t structure_size) {"
      , "#if defined(__APPLE__)"
      , "  const char *runtime = \"/usr/lib/libobjc.A.dylib\";"
      , "  if (pudu_objc_selector(cache) == NULL) {"
      , "    static pudu_foreign_cache lookup_class = {0}, register_selector = {0};"
      , "    pudu_foreign_enter();"
      , "    (void)pudu_foreign_module(site, library, version, selector, NULL);"
      , "    pudu_foreign_leave();"
      , "    if (class_name != NULL) {"
      , "      void *(*class_of)(const char *) = (void *(*)(const char *))"
      , "        pudu_foreign_function(site, &lookup_class, runtime, NULL, \"objc_getClass\", NULL);"
      , "      void *class_object = class_of(class_name);"
      , "      if (class_object == NULL) {"
      , "        char message[512];"
      , "        snprintf(message, sizeof message, \"the Objective-C runtime has no class %s\", class_name);"
      , "        pudu_foreign_enter();"
      , "        pudu_foreign_refuse(site, selector, library, NULL, message);"
      , "      }"
      , "      atomic_store_explicit(&cache->receiver, class_object, memory_order_release);"
      , "    }"
      , "    void *(*selector_of)(const char *) = (void *(*)(const char *))"
      , "      pudu_foreign_function(site, &register_selector, runtime, NULL, \"sel_registerName\", NULL);"
      , "    void *selector_token = selector_of(selector);"
      , "    if (selector_token == NULL) {"
      , "      pudu_foreign_enter();"
      , "      pudu_foreign_refuse(site, selector, library, NULL, \"the Objective-C selector is unavailable\");"
      , "    }"
      , "    atomic_store_explicit(&cache->selector, selector_token, memory_order_release);"
      , "  }"
      , "#if defined(__x86_64__)"
      , "  const char *entry = structure_size > 16 ? \"objc_msgSend_stret\" : \"objc_msgSend\";"
      , "#else"
      , "  (void)structure_size;"
      , "  const char *entry = \"objc_msgSend\";"
      , "#endif"
      , "  return pudu_foreign_function(site, &cache->dispatcher, runtime, NULL, entry, NULL);"
      , "#else"
      , "  (void)cache; (void)version; (void)class_name; (void)structure_size;"
      , "  pudu_foreign_enter();"
      , "  pudu_foreign_refuse(site, selector, library, NULL, \"Objective-C dispatch requires an Apple target\");"
      , "  return NULL;"
      , "#endif"
      , "}"
      ])
