  , ("host_foreign_loan", ["fail", "memory_failure"],
      [ "#include <setjmp.h>"
      , "typedef struct {"
      , "  jmp_buf escape;"
      , "  void (*cleanup)(void *);"
      , "  void *cleanup_data;"
      , "  int dispatched;"
      , "} pudu_foreign_loan;"
      , "typedef struct {"
      , "  pudu_site site;"
      , "  size_t length, note_length, help_length;"
      , "  const char *note, *help;"
      , "  char message[];"
      , "} pudu_foreign_report;"
      , "static _Thread_local pudu_foreign_loan *pudu_foreign_armed = NULL;"
      , "static _Thread_local pudu_foreign_report *pudu_foreign_pending = NULL;"
      , "static void pudu_foreign_loan_disarm(void) {"
      , "  pudu_report_capture_hook = NULL;"
      , "  pudu_foreign_armed = NULL;"
      , "}"
      , "/* Preserve reports whose message or note lives in the crossing frame. */"
      , "static _Noreturn void pudu_foreign_loan_capture(const pudu_site *site, const char *message, size_t length,"
      , "    const char *note, size_t note_length, const char *help, size_t help_length, void *owned_payload) {"
      , "  pudu_foreign_loan *scope = pudu_foreign_armed;"
      , "  pudu_foreign_loan_disarm();"
      , "  if (length > SIZE_MAX - sizeof(pudu_foreign_report) ||"
      , "      note_length > SIZE_MAX - sizeof(pudu_foreign_report) - length ||"
      , "      help_length > SIZE_MAX - sizeof(pudu_foreign_report) - length - note_length) pudu_memory_failure();"
      , "  pudu_foreign_report *report = malloc(sizeof *report + length + note_length + help_length);"
      , "  if (report == NULL) pudu_memory_failure();"
      , "  *report = (pudu_foreign_report){.site = *site, .length = length, .note_length = note_length, .help_length = help_length};"
      , "  if (length != 0) memcpy(report->message, message, length);"
      , "  if (note != NULL) {"
      , "    report->note = report->message + length;"
      , "    if (note_length != 0) memcpy(report->message + length, note, note_length);"
      , "  }"
      , "  if (help != NULL) {"
      , "    report->help = report->message + length + note_length;"
      , "    if (help_length != 0) memcpy(report->message + length + note_length, help, help_length);"
      , "  }"
      , "  free(owned_payload);"
      , "  if (scope->cleanup != NULL) scope->cleanup(scope->cleanup_data);"
      , "  pudu_foreign_pending = report;"
      , "  longjmp(scope->escape, 1);"
      , "}"
      , "static void pudu_foreign_loan_arm(pudu_foreign_loan *scope) {"
      , "  pudu_foreign_armed = scope;"
      , "  pudu_report_capture_hook = pudu_foreign_loan_capture;"
      , "}"
      , "static int pudu_foreign_loan_settle(void) {"
      , "  pudu_foreign_report *report = pudu_foreign_pending;"
      , "  if (report == NULL) return 0;"
      , "  pudu_foreign_pending = NULL;"
      , "  pudu_fail_noted(&report->site, report->message, report->length, report->note, report->note_length,"
      , "                  report->help, report->help_length, report);"
      , "}"
      ])
