  , ("host_foreign_lease", ["host_foreign_store", "host_gate"],
      [ "static void pudu_foreign_wait_on_gate(void) { (void)pudu_host_wait(NULL); }"
      , "static void pudu_foreign_handle_lease(pudu_box *handle, int acquire) {"
      , "  uint64_t generation = handle->fields[1].floating;"
      , "  if (generation == 0) return;"
